import { loadConfig } from '../../lib/config.js';
// /api/admin/application?id=...
//   GET    : 1건 원본 조회 (수정 화면용, 원본 열람은 접속기록에 남김)
//   PUT    : 수정 (U)
//   DELETE : 삭제 (D)
import { send, readJson, sameOrigin } from '../../lib/http.js';
import { requireAdmin } from '../../lib/auth.js';
import { getApplication, updateApplication, deleteApplication } from '../../lib/repo.js';
import { validateApplication } from '../../lib/validate.js';
import { audit } from '../../lib/audit.js';

export default async function handler(req, res) {
  if (!['GET', 'PUT', 'DELETE'].includes(req.method)) { res.setHeader('Allow', 'GET, PUT, DELETE'); return send(res, 405, { error: 'method_not_allowed' }); }
  if (req.method !== 'GET' && !sameOrigin(req)) return send(res, 403, { error: 'bad_origin' });
  await loadConfig();
  const s = await requireAdmin(req, res);
  if (!s) return;
  const id = new URL(req.url, 'http://x').searchParams.get('id') || '';
  try {
    if (req.method === 'GET') {
      const r = await getApplication(id);
      if (!r) return send(res, 404, { error: 'not_found' });
      await audit(req, 'VIEW_DETAIL', { id, fields: 'original' });
      return send(res, 200, {
        id: r.id, createdAt: r.createdAt, updatedAt: r.updatedAt,
        name: r.name, org: r.org || '', email: r.email, phone: r.phone, message: r.message || ''
      });
    }

    if (req.method === 'PUT') {
      const { data, errors, ok } = validateApplication({ ...(await readJson(req)), agree: true });
      if (!ok) return send(res, 400, { error: 'invalid', fields: Object.keys(errors) });
      const r = await updateApplication(id, data);
      if (!r) return send(res, 404, { error: 'not_found' });
      await audit(req, 'UPDATE', { id });
      return send(res, 200, { ok: true, ...r });
    }

    const done = await deleteApplication(id);
    if (!done) return send(res, 404, { error: 'not_found' });
    await audit(req, 'DELETE', { id });
    return send(res, 200, { ok: true });
  } catch (e) {
    console.error('application failed', e?.message);
    return send(res, e?.status || 500, { error: 'server_error' });
  }
}

final.api/admin/applications.js:
import { loadConfig } from '../../lib/config.js';
import { maybePurge } from '../../lib/purge.js';
// /api/admin/applications
//   GET  : 목록 조회 (R) — 이름·휴대폰·이메일은 서버에서 마스킹
//   POST : 관리자가 신청서 직접 등록 (C)
import { send, readJson, sameOrigin } from '../../lib/http.js';
import { requireAdmin } from '../../lib/auth.js';
import { listApplications, createApplication } from '../../lib/repo.js';
import { validateApplication } from '../../lib/validate.js';
import { maskName, maskPhone, maskEmail } from '../../lib/mask.js';
import { audit } from '../../lib/audit.js';

export default async function handler(req, res) {
  if (!['GET', 'POST'].includes(req.method)) { res.setHeader('Allow', 'GET, POST'); return send(res, 405, { error: 'method_not_allowed' }); }
  if (req.method !== 'GET' && !sameOrigin(req)) return send(res, 403, { error: 'bad_origin' });
  await loadConfig();
  const s = await requireAdmin(req, res);
  if (!s) return;
  try {
    if (req.method === 'POST') {
      const { data, errors, ok } = validateApplication(await readJson(req));
      if (!ok) return send(res, 400, { error: 'invalid', fields: Object.keys(errors) });
      const created = await createApplication(data, 'admin');
      await audit(req, 'CREATE', { id: created.id });
      return send(res, 201, { ok: true, ...created });
    }

    await maybePurge(); // 보관기간 지난 신청서 자동 파기 (하루 1번)
    const { rows, unreadable } = await listApplications();
    const masked = rows.map(r => ({
      id: r.id, createdAt: r.createdAt, updatedAt: r.updatedAt, createdBy: r.createdBy,
      name: maskName(r.name), phone: maskPhone(r.phone), email: maskEmail(r.email),
      org: r.org || '', message: r.message || ''
    }));
    await audit(req, 'VIEW_LIST', { count: masked.length, fields: 'masked' });
    return send(res, 200, { rows: masked, unreadable });
  } catch (e) {
    console.error('applications failed', e?.message);
    return send(res, e?.status || 500, { error: 'server_error' });
  }
}

final.api/admin/export.js:
// /api/admin/export : 신청서 전체 CSV 다운로드 (원본 데이터, 다운로드 기록 남김)
// 화면(목록)과 달리 업무 처리에 필요한 원본 연락처·동의 일시·ID까지 포함
import { loadConfig } from '../../lib/config.js';
import { send, method } from '../../lib/http.js';
import { requireAdmin } from '../../lib/auth.js';
import { listApplications } from '../../lib/repo.js';
import { audit } from '../../lib/audit.js';

const COLUMNS = [
  ['id', '신청번호'], ['createdAt', '접수일시'], ['name', '이름'], ['phone', '휴대폰'], ['email', '이메일'],
  ['org', '소속'], ['message', '질문·요청'], ['agreedAt', '개인정보 동의일시'], ['createdBy', '등록경로'], ['updatedAt', '최종수정일시']
];

const kst = iso => iso ? new Date(iso).toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' }) : '';
function cell(v) {
  let s = String(v ?? '');
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; // 엑셀 수식 실행(CSV 인젝션) 방지
  return '"' + s.replace(/"/g, '""') + '"';
}

export default async function handler(req, res) {
  if (!method(req, res, 'GET')) return;
  await loadConfig();
  const s = await requireAdmin(req, res);
  if (!s) return;
  try {
    const { rows } = await listApplications(10000);
    const lines = [COLUMNS.map(c => cell(c[1])).join(',')];
    rows.forEach(r => {
      const v = { ...r, createdAt: kst(r.createdAt), agreedAt: kst(r.agreedAt), updatedAt: kst(r.updatedAt),
        createdBy: r.createdBy === 'admin' ? '관리자 등록' : '신청서 제출' };
      lines.push(COLUMNS.map(c => cell(v[c[0]])).join(','));
    });
    await audit(req, 'EXPORT_CSV', { count: rows.length });
    const day = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Seoul' });
    res.statusCode = 200;
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="applications-${day}.csv"`);
    res.setHeader('Cache-Control', 'no-store');
    res.end('﻿' + lines.join('\r\n')); // BOM: 엑셀에서 한글 깨짐 방지
  } catch (e) {
    console.error('export failed', e?.message);
    return send(res, 500, { error: 'server_error' });
  }
}

final.api/admin/login.js:
import { loadConfig } from '../../lib/config.js';
import { send, readJson, method } from '../../lib/http.js';
import { verifyPassword, randomId } from '../../lib/security.js';
import { listPaths, putJson, stamp, stampOf } from '../../lib/store.js';
import { setSessionCookie } from '../../lib/auth.js';
import { audit } from '../../lib/audit.js';

const LOCK_WINDOW_MS = 15 * 60 * 1000;
const MAX_FAILS = 5; // 15분 안에 5회 실패하면 잠금

export default async function handler(req, res) {
  if (!method(req, res, 'POST')) return;
  try {
    await loadConfig();
    if (!process.env.ADMIN_PASSWORD_HASH) return send(res, 409, { error: 'setup_required' });
    const now = Date.now();
    const fails = (await listPaths('auth/fail/')).filter(p => now - stampOf(p) < LOCK_WINDOW_MS);
    if (fails.length >= MAX_FAILS) {
      const unlockAt = stampOf(fails[fails.length - MAX_FAILS]) + LOCK_WINDOW_MS;
      await audit(req, 'LOGIN_BLOCKED', { reason: 'locked' }, 'anonymous');
      return send(res, 423, { error: 'locked', retryAfterSec: Math.ceil((unlockAt - now) / 1000) });
    }

    const body = await readJson(req);
    if (!verifyPassword(body.password || '', process.env.ADMIN_PASSWORD_HASH)) {
      const remaining = Math.max(0, MAX_FAILS - fails.length - 1);
      await putJson(`auth/fail/${stamp(now)}-${randomId(4)}.json`, {});
      await audit(req, 'LOGIN_FAIL', { remaining }, 'anonymous');
      return send(res, 401, { error: 'invalid_credentials', remaining });
    }

    const sess = { sid: randomId(12), role: 'admin', iat: now, seen: now };
    setSessionCookie(res, sess);
    await audit(req, 'LOGIN_SUCCESS', { sid: sess.sid.slice(0, 6) });
    return send(res, 200, { ok: true });
  } catch (e) {
    console.error('login failed', e?.message);
    return send(res, e?.status || 500, { error: 'server_error' });
  }
}

final.api/admin/logout.js:
import { loadConfig } from '../../lib/config.js';
import { send, method } from '../../lib/http.js';
import { readSession, clearSessionCookie } from '../../lib/auth.js';
import { putJson, stamp } from '../../lib/store.js';
import { audit } from '../../lib/audit.js';

export default async function handler(req, res) {
  if (!method(req, res, 'POST')) return;
  await loadConfig();
  const s = readSession(req);
  if (s) {
    await putJson(`auth/revoked/${s.sid}-${stamp()}.json`, { at: Date.now() }); // 서버에서도 세션 폐기
    await audit(req, 'LOGOUT', { sid: s.sid.slice(0, 6) });
  }
  clearSessionCookie(res);
  return send(res, 200, { ok: true });
}

