import { send, method } from '../../lib/http.js';
import { readSession } from '../../lib/auth.js';
import { IDLE_MS } from '../../lib/security.js';
import { loadConfig, adminConfigured } from '../../lib/config.js';

export default async function handler(req, res) {
  if (!method(req, res, 'GET')) return;
  try {
    await loadConfig();
    if (!adminConfigured()) return send(res, 200, { authenticated: false, setupRequired: true });
    const s = readSession(req);
    return send(res, 200, { authenticated: !!s, idleTimeoutSec: IDLE_MS / 1000 });
  } catch (e) {
    console.error('session failed', e?.message);
    return send(res, 500, { error: 'server_error' });
  }
}

final.api/admin/setup.js:
// 최초 설정: 관리자가 정한 비밀번호의 해시만 비공개 저장소에 저장 (최초 1회만 가능)
// 한 번 등록되면 이 API는 더 이상 동작하지 않음.
import { send, readJson, method } from '../../lib/http.js';
import { hashPassword, randomId } from '../../lib/security.js';
import { putJson } from '../../lib/store.js';
import { loadConfig, adminConfigured } from '../../lib/config.js';
import { setSessionCookie } from '../../lib/auth.js';
import { audit } from '../../lib/audit.js';

export default async function handler(req, res) {
  if (!method(req, res, 'POST')) return;
  try {
    await loadConfig();
    if (adminConfigured()) return send(res, 403, { error: 'already_configured' });
    const body = await readJson(req);
    const pw = String(body.password || '');
    if (pw.length < 12 || pw.length > 128 || !/[A-Za-z]/.test(pw) || !/\d/.test(pw)) {
      return send(res, 400, { error: 'weak_password' });
    }
    const hash = hashPassword(pw);
    try {
      await putJson('system/admin.json', { hash, createdAt: new Date().toISOString() }, { once: true });
    } catch {
      return send(res, 403, { error: 'already_configured' }); // 누군가 먼저 등록함
    }
    process.env.ADMIN_PASSWORD_HASH = hash;
    const now = Date.now();
    const sess = { sid: randomId(12), role: 'admin', iat: now, seen: now };
    setSessionCookie(res, sess);
    await audit(req, 'ADMIN_SETUP', {});
    return send(res, 200, { ok: true });
  } catch (e) {
    console.error('setup failed', e?.message);
    return send(res, 500, { error: 'server_error' });
  }
}

final.api/apply.js:
import { loadConfig } from '../lib/config.js';
import { send, readJson, method, clientIp } from '../lib/http.js';
import { validateApplication } from '../lib/validate.js';
import { randomId, sha256 } from '../lib/security.js';
import { createApplication } from '../lib/repo.js';
import { putJson, listPaths, stamp, stampOf } from '../lib/store.js';

const WINDOW_MS = 10 * 60 * 1000;
const MAX_PER_WINDOW = 5; // 같은 IP에서 10분에 5건까지

export default async function handler(req, res) {
  if (!method(req, res, 'POST')) return;
  try {
    await loadConfig();
    const body = await readJson(req);
    if (body.website) return send(res, 200, { ok: true }); // 봇용 숨은 칸(honeypot)

    const { data, errors, ok } = validateApplication(body);
    if (!ok) return send(res, 400, { error: 'invalid', fields: Object.keys(errors) });

    const now = Date.now();
    const ipKey = sha256(clientIp(req) + (process.env.SESSION_SECRET || '')).slice(0, 24);
    const recent = (await listPaths(`rl/apply/${ipKey}/`)).filter(p => now - stampOf(p) < WINDOW_MS);
    if (recent.length >= MAX_PER_WINDOW) return send(res, 429, { error: 'too_many' });
    await putJson(`rl/apply/${ipKey}/${stamp(now)}-${randomId(4)}.json`, {});

    const created = await createApplication(data, 'applicant');
    return send(res, 200, { ok: true, ...created });
  } catch (e) {
    console.error('apply failed', e?.message);
    return send(res, e?.status || 500, { error: 'server_error' });
  }
}

final.api/cron/purge.js:
// 매일 실행 (CRON_SECRET 환경변수가 있을 때). 없으면 관리자 목록 조회 시 하루 1번 자동 실행됨.
import crypto from 'node:crypto';
import { send } from '../../lib/http.js';
import { loadConfig } from '../../lib/config.js';
import { purgeOld } from '../../lib/purge.js';

export default async function handler(req, res) {
  const want = `Bearer ${process.env.CRON_SECRET || ''}`;
  const got = String(req.headers.authorization || '');
  if (!process.env.CRON_SECRET || got.length !== want.length ||
      !crypto.timingSafeEqual(Buffer.from(got), Buffer.from(want))) {
    return send(res, 401, { error: 'unauthorized' });
  }
  await loadConfig();
  const n = await purgeOld();
  return send(res, 200, { ok: true, purgedApplications: n });
}

final.app.js:
const form = document.getElementById('applyForm');
const formArea = document.getElementById('formArea');
const result = document.getElementById('result');
const nameInput = document.getElementById('name');
const orgInput = document.getElementById('org');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const messageInput = document.getElementById('message');
const agreeInput = document.getElementById('agree');
const msgCounter = document.getElementById('msgCounter');
const errSummary = document.getElementById('errSummary');

const ORDER = ['f-name', 'f-email', 'f-phone', 'f-agree'];
const LABELS = { 'f-name': '이름', 'f-email': '이메일', 'f-phone': '휴대폰', 'f-agree': '개인정보 동의' };
const INPUTS = { 'f-name': nameInput, 'f-email': emailInput, 'f-phone': phoneInput, 'f-agree': agreeInput };

const dirty = {};            // 한 번이라도 입력한 칸
const noticeTimers = {};     // 입력 중 안내를 자동으로 숨기는 타이머
let submitAttempted = false; // 제출을 한 번이라도 시도했는지
let typoShownFor = '';       // 오타 안내를 이미 보여 준 이메일

// 이메일 흔한 오타 -> 올바른 주소
const EMAIL_TYPOS = {
  'gmail.con': 'gmail.com', 'gmail.co': 'gmail.com', 'gmial.com': 'gmail.com',
  'gamil.com': 'gmail.com', 'gmai.com': 'gmail.com',
  'naver.con': 'naver.com', 'naver.co': 'naver.com', 'naber.com': 'naver.com', 'nave.com': 'naver.com',
  'daum.nett': 'daum.net', 'nate.con': 'nate.com', 'outlook.con': 'outlook.com'
};

// ---------- 화면 표시 도우미 ----------
function showNotice(fieldId, msg, persist) {
  const el = document.getElementById('notice-' + fieldId.slice(2));
  clearTimeout(noticeTimers[fieldId]);
  el.textContent = msg;
  el.classList.add('show');
  if (!persist) noticeTimers[fieldId] = setTimeout(() => hideNotice(fieldId), 2500);
}

function hideNotice(fieldId) {
  const el = document.getElementById('notice-' + fieldId.slice(2));
  if (!el) return;
  clearTimeout(noticeTimers[fieldId]);
  el.classList.remove('show');
  el.textContent = '';
}

// msg가 비어 있으면 통과(초록 체크), 있으면 오류 문구 표시
function setState(fieldId, msg, showValid) {
  const field = document.getElementById(fieldId);
  document.getElementById('err-' + fieldId.slice(2)).textContent = msg;
  field.classList.toggle('invalid', !!msg);
  field.classList.toggle('valid', !msg && !!showValid);
  return !msg;
}

function resetState(fieldId) {
  const field = document.getElementById(fieldId);
  field.classList.remove('invalid', 'valid');
}

// 입력을 시작하면 이전 오류/체크 표시를 지움
function touch(fieldId) {
  dirty[fieldId] = true;
  resetState(fieldId);
  refreshSummary();
}

// ---------- 제출 시 오류 요약 ----------
function refreshSummary() {
  if (!submitAttempted) return;
  const bad = ORDER.filter(id => document.getElementById(id).classList.contains('invalid'));
  if (bad.length === 0) {
    errSummary.classList.remove('show');
    return;
  }
  errSummary.textContent = '';
  const strong = document.createElement('strong');
  strong.textContent = '확인이 필요한 항목이 ' + bad.length + '개 있어요: ';
  errSummary.appendChild(strong);
  bad.forEach((id, i) => {
    if (i > 0) errSummary.appendChild(document.createTextNode(', '));
    const a = document.createElement('a');
    a.href = '#';
    a.textContent = LABELS[id];
    a.addEventListener('click', (e) => { e.preventDefault(); focusField(id); });
    errSummary.appendChild(a);
  });
  errSummary.classList.add('show');
}

function focusField(id) {
  document.getElementById(id).scrollIntoView({ behavior: 'smooth', block: 'center' });
  INPUTS[id].focus({ preventScroll: true });
}

// ---------- 입력 중 처리 + 안내 ----------
nameInput.addEventListener('input', () => {
  const raw = nameInput.value;
  const v = raw
    .replace(/[^가-힣ㄱ-ㅎㅏ-ㅣa-zA-Z ]/g, '')
    .replace(/^ +/, '')
    .replace(/ {2,}/g, ' ');
  if (/[^가-힣ㄱ-ㅎㅏ-ㅣa-zA-Z ]/.test(raw)) {
    showNotice('f-name', '이름에는 한글과 영문만 입력할 수 있어요. (숫자·특수문자 불가)');
  }
  if (v !== raw) nameInput.value = v;
  touch('f-name');
});

orgInput.addEventListener('input', () => {});

emailInput.addEventListener('input', () => {
  const raw = emailInput.value;
  const v = raw.replace(/[^\x21-\x7E]/g, '');
  hideNotice('f-email');
  if (v !== raw) {
    emailInput.value = v;
    showNotice('f-email', '이메일에는 한글과 공백을 쓸 수 없어요.');
  }
  touch('f-email');
});

phoneInput.addEventListener('input', () => {
  const raw = phoneInput.value;
  if (/[^\d-]/.test(raw)) showNotice('f-phone', '휴대폰 번호는 숫자만 입력할 수 있어요.');
  const d = raw.replace(/\D/g, '').slice(0, 11);
  if (d.length < 4) phoneInput.value = d;
  else if (d.length < 8) phoneInput.value = d.slice(0, 3) + '-' + d.slice(3);
  else phoneInput.value = d.slice(0, 3) + '-' + d.slice(3, 7) + '-' + d.slice(7);
  touch('f-phone');
});

// 질문/요청: 글자 수 표시, 450자부터 남은 글자 수 안내
function updateCounter() {
  const len = messageInput.value.length;
  if (len >= 450) {
    msgCounter.textContent = '500자까지 쓸 수 있어요. 지금 ' + (500 - len) + '자 남았어요.';
    msgCounter.classList.add('warn');
  } else {
    msgCounter.textContent = len + ' / 500자';
    msgCounter.classList.remove('warn');
  }
}
messageInput.addEventListener('input', updateCounter);

// ---------- 상황별 오류 문구 ----------
function checkName(v) {
  if (!v) return '이름을 입력해 주세요.';
  if (v.length < 2) return '이름은 2자 이상 입력해 주세요.';
  if (!/^[가-힣a-zA-Z]+( [가-힣a-zA-Z]+)*$/.test(v)) return '이름에는 한글과 영문만 입력할 수 있어요.';
  return '';
}

function checkEmail(v) {
  if (!v) return '이메일을 입력해 주세요.';
  if (!v.includes('@')) return '이메일에 @가 빠져 있어요. 예: example@email.com';
  const domain = v.slice(v.indexOf('@') + 1);
  if (!domain || !domain.includes('.') || domain.endsWith('.')) {
    return '@ 뒤에 주소를 입력해 주세요. 예: naver.com';
  }
  if (!/^[A-Za-z0-9._%+\-]+@[A-Za-z0-9\-]+(\.[A-Za-z0-9\-]+)*\.[A-Za-z]{2,}$/.test(v)) {
    return '올바른 이메일 주소를 입력해 주세요. 예: example@email.com';
  }
  return '';
}

function typoFix(v) {
  return EMAIL_TYPOS[v.slice(v.indexOf('@') + 1).toLowerCase()] || '';
}

function checkPhone(v) {
  if (!v) return '휴대폰 번호를 입력해 주세요.';
  const digits = v.replace(/\D/g, '');
  if (digits.length >= 3 && !/^01[016789]/.test(digits)) return '휴대폰 번호는 010으로 시작해요.';
  if (digits.length < 11) return '번호가 아직 짧아요. 숫자 11자리를 입력해 주세요.';
  if (!/^01[016789]-\d{3,4}-\d{4}$/.test(v)) return '휴대폰 번호를 올바르게 입력해 주세요. 예: 010-1234-5678';
  return '';
}

function checkAgree(checked) {
  return checked ? '' : '개인정보 수집·이용에 동의해 주셔야 신청할 수 있어요.';
}

// ---------- 칸별 검사 ----------
function validateEmail(fromSubmit) {
  const v = emailInput.value.trim();
  hideNotice('f-email');
  let msg = checkEmail(v);
  if (!msg) {
    const fix = typoFix(v);
    if (fix) {
      if (fromSubmit && typoShownFor !== v) {
        typoShownFor = v;
        msg = '혹시 ' + fix + ' 아닌가요? 맞는 주소라면 그대로 한 번 더 제출해 주세요.';
      } else if (!fromSubmit) {
        typoShownFor = v;
        resetState('f-email');
        document.getElementById('err-email').textContent = '';
        showNotice('f-email', '혹시 ' + fix + ' 아닌가요? 맞는 주소라면 그대로 두셔도 돼요.', true);
        return true;
      }
    }
  }
  return setState('f-email', msg, true);
}

function validate(id, fromSubmit) {
  if (id === 'f-name') return setState(id, checkName(nameInput.value.trim()), true);
  if (id === 'f-email') return validateEmail(fromSubmit);
  if (id === 'f-phone') return setState(id, checkPhone(phoneInput.value.trim()), true);
  if (id === 'f-agree') return setState(id, checkAgree(agreeInput.checked), false);
  return true;
}

// 칸을 벗어날 때 그 칸만 바로 검사 (한 번도 입력하지 않은 칸은 건너뜀)
function blurCheck(id) {
  if (!dirty[id]) return;
  validate(id, false);
  refreshSummary();
}
nameInput.addEventListener('blur', () => blurCheck('f-name'));
emailInput.addEventListener('blur', () => blurCheck('f-email'));
phoneInput.addEventListener('blur', () => blurCheck('f-phone'));

agreeInput.addEventListener('change', () => {
  if (agreeInput.checked || submitAttempted) validate('f-agree', false);
  refreshSummary();
});

// ---------- 제출 ----------
const submitBtn = document.getElementById('submitBtn');
const submitErr = document.getElementById('submitErr');

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  submitAttempted = true;
  submitErr.classList.remove('show');

  // 소속과 질문/요청은 선택 항목이라 검사하지 않습니다.
  const results = ORDER.map(id => ({ id, ok: validate(id, true) }));
  refreshSummary();

  const firstBad = results.find(r => !r.ok);
  if (firstBad) {
    focusField(firstBad.id);
    return;
  }

  const data = {
    name: nameInput.value.trim(),
    org: orgInput.value.trim(),
    email: emailInput.value.trim(),
    phone: phoneInput.value.trim(),
    message: messageInput.value.trim(),
    agree: agreeInput.checked,
    website: document.getElementById('website').value
  };

  // 서버로 전송 (브라우저에는 신청 내용을 저장하지 않음)
  submitBtn.disabled = true;
  submitBtn.textContent = '제출 중...';
  try {
    const r = await fetch('/api/apply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) {
      submitErr.textContent = r.status === 429
        ? '잠시 후 다시 시도해 주세요. (짧은 시간에 너무 많이 제출됐어요)'
        : r.status === 400
          ? '입력 내용을 다시 확인해 주세요.'
          : '제출 중 문제가 생겼어요. 잠시 후 다시 시도해 주세요.';
      submitErr.classList.add('show');
      return;
    }
    data.submittedAt = new Date(j.createdAt || Date.now()).toLocaleString('ko-KR');
  } catch {
    submitErr.textContent = '네트워크 연결을 확인한 뒤 다시 시도해 주세요.';
    submitErr.classList.add('show');
    return;
  } finally {
    submitBtn.disabled = false;
    submitBtn.textContent = '신청서 제출';
  }

  document.getElementById('summary').textContent =
    '이름: ' + data.name + '\n' +
    '소속: ' + (data.org || '(없음)') + '\n' +
    '이메일: ' + data.email + '\n' +
    '휴대폰: ' + data.phone + '\n' +
    '질문/요청: ' + (data.message || '(없음)') + '\n' +
    '개인정보 동의: 동의함\n' +
    '접수 시각: ' + data.submittedAt;

  formArea.style.display = 'none';
  result.style.display = 'block';
  window.scrollTo(0, 0);
});

document.getElementById('resetBtn').addEventListener('click', () => {
  form.reset();
  typoShownFor = '';
  submitAttempted = false;
  Object.keys(dirty).forEach(k => delete dirty[k]);
  ORDER.forEach(id => {
    resetState(id);
    hideNotice(id);
    document.getElementById('err-' + id.slice(2)).textContent = '';
  });
  errSummary.classList.remove('show');
  errSummary.textContent = '';
  updateCounter();
  result.style.display = 'none';
  formArea.style.display = 'block';
});

// ================= 탭 =================
const views = { apply: document.getElementById('view-apply'), admin: document.getElementById('view-admin') };
const tabsEl = document.getElementById('tabs');
function showView(name) {
  Object.entries(views).forEach(([k, el]) => el.classList.toggle('hidden', k !== name));
  document.querySelectorAll('.tab').forEach(t => t.setAttribute('aria-selected', String(t.dataset.view === name)));
  if (name === 'admin') initAdmin();
  window.scrollTo(0, 0);
}
document.querySelectorAll('.tab').forEach(t => t.addEventListener('click', () => {
  history.replaceState(null, '', t.dataset.view === 'admin' ? '#admin' : '#');
  showView(t.dataset.view);
}));
window.addEventListener('hashchange', () => showView(location.hash === '#admin' ? 'admin' : 'apply'));

// ================= 관리자 =================
const $ = id => document.getElementById(id);
const setupCard = $('adminSetup'), loginCard = $('adminLogin'), panel = $('adminPanel');
const rowsEl = $('rows'), logRowsEl = $('logRows');
let allRows = [];

function showOnly(card) {
  [setupCard, loginCard, panel].forEach(c => c.classList.toggle('hidden', c !== card));
  tabsEl.classList.toggle('wide', card === panel);
}
function showLogin(msg) {
  showOnly(loginCard);
  $('adminPw').value = '';
  $('loginErr').textContent = msg || '';
  $('loginErr').classList.toggle('show', !!msg);
  setTimeout(() => $('adminPw').focus(), 0);
}
function showPanel() { showOnly(panel); loadRows(); }

let toastTimer;
function toast(msg) {
  const t = $('toast'); t.textContent = msg; t.classList.add('show');
  clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove('show'), 2200);
}

// 공통 API 호출: 세션이 끝났으면 로그인 화면으로
async function api(path, opts = {}) {
  const r = await fetch(path, { credentials: 'same-origin', ...opts });
  if (r.status === 401 && path !== '/api/admin/login') {
    showLogin('로그인 시간이 지났어요. 다시 로그인해 주세요.');
    throw new Error('unauthorized');
  }
  return r;
}
const jsonOpts = (method, body) => ({ method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

let adminChecked = false;
async function initAdmin() {
  if (adminChecked) return;
  adminChecked = true;
  try {
    const j = await (await fetch('/api/admin/session', { credentials: 'same-origin' })).json();
    if (j.setupRequired) showOnly(setupCard);
    else if (j.authenticated) showPanel();
    else showLogin();
  } catch { showLogin(); }
}

// ---------- 최초 설정 ----------
$('setupForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const err = $('setupErr'), pw = $('setupPw').value, pw2 = $('setupPw2').value;
  let msg = '';
  if (pw.length < 12 || !/[A-Za-z]/.test(pw) || !/\d/.test(pw)) msg = '비밀번호는 12자 이상, 영문과 숫자를 모두 포함해 주세요.';
  else if (pw !== pw2) msg = '비밀번호 확인이 일치하지 않아요.';
  err.textContent = msg; err.classList.toggle('show', !!msg);
  if (msg) return;
  $('setupBtn').disabled = true;
  try {
    const r = await fetch('/api/admin/setup', jsonOpts('POST', { password: pw }));
    $('setupPw').value = ''; $('setupPw2').value = '';
    if (r.status === 403) { showLogin('이미 관리자 비밀번호가 등록돼 있어요. 로그인해 주세요.'); return; }
    if (!r.ok) throw new Error();
    toast('관리자 비밀번호를 등록했어요.');
    showPanel();
  } catch {
    err.textContent = '등록하지 못했어요. 잠시 후 다시 시도해 주세요.'; err.classList.add('show');
  } finally { $('setupBtn').disabled = false; }
});

// ---------- 로그인 (비밀번호만) ----------
$('loginForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const err = $('loginErr');
  if (!$('adminPw').value) { err.textContent = '비밀번호를 입력해 주세요.'; err.classList.add('show'); return; }
  $('loginBtn').disabled = true;
  try {
    const r = await api('/api/admin/login', jsonOpts('POST', { password: $('adminPw').value }));
    const j = await r.json().catch(() => ({}));
    $('adminPw').value = '';
    if (r.ok) { err.classList.remove('show'); showPanel(); return; }
    err.textContent = r.status === 423
      ? '로그인 실패가 많아 잠겼어요. 약 ' + Math.ceil((j.retryAfterSec || 900) / 60) + '분 뒤에 다시 시도해 주세요.'
      : r.status === 401
        ? '비밀번호가 맞지 않아요. (남은 시도 ' + (j.remaining ?? '-') + '회)'
        : '로그인 중 문제가 생겼어요. 잠시 후 다시 시도해 주세요.';
    err.classList.add('show');
  } catch {} finally { $('loginBtn').disabled = false; }
});

$('logoutBtn').addEventListener('click', async () => {
  try { await api('/api/admin/logout', { method: 'POST' }); } catch {}
  allRows = []; rowsEl.textContent = ''; logRowsEl.textContent = '';
  showLogin();
});

// ---------- 목록 (R) ----------
function cell(text, cls) {
  const el = document.createElement('td');
  el.textContent = text;   // textContent만 사용 (XSS 방지)
  if (cls) el.className = cls;
  return el;
}
const fmt = iso => new Date(iso).toLocaleString('ko-KR', { dateStyle: 'short', timeStyle: 'short' });
function emptyRow(colspan, text) {
  const tr = document.createElement('tr'); const td = cell(text, 'empty'); td.colSpan = colspan; tr.appendChild(td); return tr;
}

function renderStats() {
  const now = new Date(), today = now.toDateString(), weekAgo = now - 7 * 864e5;
  $('statTotal').textContent = allRows.length;
  $('statToday').textContent = allRows.filter(r => new Date(r.createdAt).toDateString() === today).length;
  $('statWeek').textContent = allRows.filter(r => new Date(r.createdAt) >= weekAgo).length;
}

function renderRows() {
  const q = $('searchInput').value.trim().toLowerCase();
  const list = q ? allRows.filter(r => [r.org, r.message, r.email, r.name, r.phone].join(' ').toLowerCase().includes(q)) : allRows;
  rowsEl.textContent = '';
  if (!list.length) { rowsEl.appendChild(emptyRow(7, q ? '검색 결과가 없어요.' : '아직 접수된 신청서가 없어요.')); return; }
  list.forEach(r => {
    const tr = document.createElement('tr');
    const when = cell(fmt(r.createdAt), 'mono');
    if (r.updatedAt) { const t = document.createElement('span'); t.className = 'tag'; t.textContent = '수정됨'; when.appendChild(t); }
    const act = cell('', 'act');
    const edit = document.createElement('button'); edit.type = 'button'; edit.className = 'ghost'; edit.textContent = '수정';
    edit.addEventListener('click', () => openEdit(r.id));
    const del = document.createElement('button'); del.type = 'button'; del.className = 'danger'; del.textContent = '삭제';
    del.addEventListener('click', () => removeRow(r));
    act.append(edit, del);
    tr.append(when, cell(r.name), cell(r.phone, 'mono'), cell(r.email), cell(r.org || '-'), cell(r.message || '-', 'msg'), act);
    rowsEl.appendChild(tr);
  });
}

async function loadRows() {
  rowsEl.textContent = ''; rowsEl.appendChild(emptyRow(7, '불러오는 중...'));
  try {
    const j = await (await api('/api/admin/applications')).json();
    allRows = j.rows || [];
    renderStats(); renderRows();
    if ($('logsBox').open) loadLogs();
  } catch (e) {
    if (e.message !== 'unauthorized') { rowsEl.textContent = ''; rowsEl.appendChild(emptyRow(7, '목록을 불러오지 못했어요.')); }
  }
}
$('searchInput').addEventListener('input', renderRows);
$('refreshBtn').addEventListener('click', loadRows);

// ---------- 추가 (C) · 수정 (U) ----------
const dlg = $('editDialog');
let editingId = null;
const F = { name: $('eName'), org: $('eOrg'), email: $('eEmail'), phone: $('ePhone'), message: $('eMsg') };

F.phone.addEventListener('input', () => {
  const d = F.phone.value.replace(/\D/g, '').slice(0, 11);
  F.phone.value = d.length < 4 ? d : d.length < 8 ? d.slice(0, 3) + '-' + d.slice(3) : d.slice(0, 3) + '-' + d.slice(3, 7) + '-' + d.slice(7);
});

function openDialog(title, values, isNew) {
  editingId = isNew ? null : values.id;
  $('editTitle').textContent = title;
  Object.keys(F).forEach(k => { F[k].value = values[k] || ''; });
  $('eAgree').checked = false;
  $('eAgreeRow').classList.toggle('hidden', !isNew);
  $('editErr').classList.remove('show');
  dlg.showModal();
  F.name.focus();
}
$('addBtn').addEventListener('click', () => openDialog('신청 추가', {}, true));

async function openEdit(id) {
  try {
    const r = await api('/api/admin/application?id=' + encodeURIComponent(id));
    if (!r.ok) { toast('신청서를 찾을 수 없어요.'); return loadRows(); }
    openDialog('신청 수정', await r.json(), false);
  } catch {}
}

function checkEdit() {
  const v = Object.fromEntries(Object.entries(F).map(([k, el]) => [k, el.value.trim()]));
  if (checkName(v.name)) return checkName(v.name);
  if (checkEmail(v.email)) return checkEmail(v.email);
  if (checkPhone(v.phone)) return checkPhone(v.phone);
  if (!editingId && !$('eAgree').checked) return '신청자의 개인정보 수집·이용 동의 여부를 확인해 주세요.';
  return '';
}

$('editCancel').addEventListener('click', () => dlg.close());
$('editForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const err = $('editErr'), msg = checkEdit();
  err.textContent = msg; err.classList.toggle('show', !!msg);
  if (msg) return;
  const body = Object.fromEntries(Object.entries(F).map(([k, el]) => [k, el.value.trim()]));
  $('editSave').disabled = true;
  try {
    const r = editingId
      ? await api('/api/admin/application?id=' + encodeURIComponent(editingId), jsonOpts('PUT', body))
      : await api('/api/admin/applications', jsonOpts('POST', { ...body, agree: true }));
    if (!r.ok) { err.textContent = r.status === 400 ? '입력 내용을 다시 확인해 주세요.' : '저장하지 못했어요. 잠시 후 다시 시도해 주세요.'; err.classList.add('show'); return; }
    dlg.close();
    toast(editingId ? '수정했어요.' : '신청서를 추가했어요.');
    loadRows();
  } catch {} finally { $('editSave').disabled = false; }
});

// ---------- 삭제 (D) ----------
async function removeRow(r) {
  if (!confirm(r.name + ' (' + r.phone + ') 신청서를 삭제할까요?\n삭제하면 되돌릴 수 없어요.')) return;
  try {
    const res = await api('/api/admin/application?id=' + encodeURIComponent(r.id), { method: 'DELETE' });
    toast(res.ok ? '삭제했어요.' : '삭제하지 못했어요.');
    loadRows();
  } catch {}
}

// ---------- CSV 전체 다운로드 ----------
$('csvBtn').addEventListener('click', () => {
  if (!confirm('CSV에는 마스킹 없는 원본 이름·연락처가 들어가요.\n다운로드 기록이 남고, 파일은 업무가 끝나면 바로 삭제해 주세요.\n다운로드할까요?')) return;
  location.href = '/api/admin/export';
  setTimeout(() => { if ($('logsBox').open) loadLogs(); }, 1500);
});

// ---------- 접속기록 ----------
const ACTIONS = { ADMIN_SETUP: '관리자 비밀번호 최초 등록', LOGIN_SUCCESS: '로그인 성공', LOGIN_FAIL: '로그인 실패', LOGIN_BLOCKED: '로그인 차단(잠금)', LOGOUT: '로그아웃',
  VIEW_LIST: '목록 조회', VIEW_DETAIL: '원본 열람(수정 화면)', CREATE: '신청 추가', EXPORT_CSV: 'CSV 전체 다운로드', UPDATE: '신청 수정', DELETE: '신청 삭제',
  VIEW_LOGS: '접속기록 조회', PURGE: '보관기간 경과 자동 파기' };
async function loadLogs() {
  logRowsEl.textContent = ''; logRowsEl.appendChild(emptyRow(5, '불러오는 중...'));
  try {
    const j = await (await api('/api/admin/logs')).json();
    logRowsEl.textContent = '';
    (j.logs || []).forEach(l => {
      const tr = document.createElement('tr');
      tr.append(cell(fmt(l.at), 'mono'), cell(l.actor), cell(ACTIONS[l.action] || l.action), cell(l.ip, 'mono'),
        cell(l.detail && Object.keys(l.detail).length ? JSON.stringify(l.detail) : '-'));
      logRowsEl.appendChild(tr);
    });
  } catch {}
}
$('logsBox').addEventListener('toggle', e => { if (e.target.open) loadLogs(); });

showView(location.hash === '#admin' ? 'admin' : 'apply');

