export function send(res, status, obj) {
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow');
  res.end(JSON.stringify(obj));
}

export async function readJson(req, limit = 8 * 1024) {
  if (req.body && typeof req.body === 'object') return req.body;
  return new Promise((resolve, reject) => {
    let size = 0; const chunks = [];
    req.on('data', c => {
      size += c.length;
      if (size > limit) { reject(Object.assign(new Error('too large'), { status: 413 })); req.destroy(); }
      else chunks.push(c);
    });
    req.on('end', () => {
      try { resolve(chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {}); }
      catch { reject(Object.assign(new Error('bad json'), { status: 400 })); }
    });
    req.on('error', reject);
  });
}

export function clientIp(req) {
  const xf = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim();
  return xf || String(req.headers['x-real-ip'] || req.socket?.remoteAddress || 'unknown');
}

export function cookies(req) {
  const out = {};
  String(req.headers.cookie || '').split(';').forEach(p => {
    const i = p.indexOf('=');
    if (i > 0) out[p.slice(0, i).trim()] = decodeURIComponent(p.slice(i + 1).trim());
  });
  return out;
}

// CSRF 방어: 상태를 바꾸는 요청은 같은 출처에서 온 것만 허용
export function sameOrigin(req) {
  const origin = req.headers.origin;
  if (!origin) return false;
  try { return new URL(origin).host === req.headers.host; } catch { return false; }
}

export function method(req, res, allowed) {
  if (req.method !== allowed) {
    res.setHeader('Allow', allowed);
    send(res, 405, { error: 'method_not_allowed' });
    return false;
  }
  if (allowed !== 'GET' && !sameOrigin(req)) {
    send(res, 403, { error: 'bad_origin' });
    return false;
  }
  return true;
}

final.lib/mask.js:
// 마스킹은 서버에서만 처리 (원본은 브라우저로 보내지 않음)
export function maskName(name) {
  const chars = [...String(name || '')];
  if (chars.length <= 1) return chars.join('') + '*';
  return chars[0] + '*'.repeat(chars.length - 1);
}

export function maskPhone(phone) {
  const m = String(phone || '').match(/^(\d{3})-?\d{3,4}-?(\d{4})$/);
  return m ? `${m[1]}-****-${m[2]}` : '***-****-****';
}

export function maskEmail(email) {
  const [id, domain] = String(email || '').split('@');
  if (!domain) return '***';
  return id.slice(0, 2) + '***@' + domain;
}

final.lib/purge.js:
// 보관기간이 지난 데이터 파기 (매일 크론 + 관리자 목록 조회 시 하루 1번 자동 실행)
import { listPaths, delPaths, stampOf, putJson, getJson, stamp } from './store.js';
import { randomId } from './security.js';

const DAY = 24 * 60 * 60 * 1000;

export async function purgeOld() {
  const now = Date.now();
  const retentionDays = Number(process.env.RETENTION_DAYS || 90);
  const old = async (prefix, ms) => (await listPaths(prefix)).filter(p => now - stampOf(p) > ms);

  const apps = await old('applications/', retentionDays * DAY);
  const logs = await old('logs/', 730 * DAY); // 접속기록 2년 보관
  const fails = await old('auth/fail/', DAY);
  const rl = await old('rl/', DAY);
  const revoked = await old('auth/revoked/', DAY);
  await delPaths([...apps, ...logs, ...fails, ...rl, ...revoked]);

  await putJson('system/last-purge.json', { at: now });
  await putJson(`logs/${stamp(now)}-${randomId(6)}.json`, {
    at: new Date(now).toISOString(), actor: 'system', action: 'PURGE',
    ip: '-', ua: 'auto', detail: { applications: apps.length, retentionDays }
  });
  return apps.length;
}

export async function maybePurge() {
  try {
    const last = await getJson('system/last-purge.json');
    if (!last || Date.now() - last.at > DAY) await purgeOld();
  } catch (e) {
    console.error('purge failed', e?.message);
  }
}

final.lib/repo.js:
// 신청서 저장소 (CRUD). 레코드 1건 = applications/<생성시각>-<id>.json (본문은 AES 암호화)
import { putJson, getJson, listPaths, delPaths, stamp } from './store.js';
import { encrypt, decrypt, randomId } from './security.js';

const ID_RE = /^[A-Za-z0-9_-]{12}$/;

async function pathOf(id) {
  if (!ID_RE.test(String(id || ''))) return null;
  return (await listPaths('applications/')).find(p => p.endsWith(`-${id}.json`)) || null;
}

// C: 생성
export async function createApplication(data, by = 'applicant') {
  const now = Date.now();
  const id = randomId(9);
  const record = { ...data, agree: true, agreedAt: new Date(now).toISOString() };
  const doc = { id, createdAt: new Date(now).toISOString(), updatedAt: null, createdBy: by, enc: encrypt(record) };
  await putJson(`applications/${stamp(now)}-${id}.json`, doc);
  return { id, createdAt: doc.createdAt };
}

// R: 목록 (최신순, 복호화된 원본 반환 → 호출하는 쪽에서 마스킹)
export async function listApplications(limit = 500) {
  const paths = (await listPaths('applications/')).reverse().slice(0, limit);
  const docs = (await Promise.all(paths.map(getJson))).filter(Boolean);
  let unreadable = 0;
  const rows = docs.map(doc => {
    try { return { ...meta(doc), ...decrypt(doc.enc) }; } catch { unreadable++; return null; }
  }).filter(Boolean);
  return { rows, unreadable };
}

// R: 1건
export async function getApplication(id) {
  const p = await pathOf(id);
  if (!p) return null;
  const doc = await getJson(p);
  return doc ? { ...meta(doc), ...decrypt(doc.enc) } : null;
}

// U: 수정 (생성 시각·동의 기록 유지)
export async function updateApplication(id, data) {
  const p = await pathOf(id);
  if (!p) return null;
  const doc = await getJson(p);
  if (!doc) return null;
  const old = decrypt(doc.enc);
  const record = { ...old, ...data };
  doc.updatedAt = new Date().toISOString();
  doc.enc = encrypt(record);
  await putJson(p, doc);
  return meta(doc);
}

// D: 삭제 (즉시 파기)
export async function deleteApplication(id) {
  const p = await pathOf(id);
  if (!p) return false;
  await delPaths([p]);
  return true;
}

function meta(doc) {
  return { id: doc.id, createdAt: doc.createdAt, updatedAt: doc.updatedAt || null, createdBy: doc.createdBy || 'applicant' };
}

